class SQLQueryBuilder:

    @staticmethod
    def select(table, columns='*', where=None):
        if columns == '*':
            column_clause = '*'
        elif isinstance(columns, list):
            column_clause = ', '.join(columns)
        else:
            column_clause = columns

        query_parts = [f'SELECT {column_clause} FROM {table}']

        if where and isinstance(where, dict):
            conditions = []
            for key, value in where.items():
                conditions.append(f"{key}='{value}'")

            if conditions:
                query_parts.append(f"WHERE {' AND '.join(conditions)}")

        return ' '.join(query_parts)

    @staticmethod
    def insert(table, data):
        if not isinstance(data, dict):
            raise TypeError("data must be a dictionary")

        columns = list(data.keys())
        columns_clause = ', '.join(columns)
        # Escape single quotes to prevent SQL injection
        values = ', '.join(f"'{v.replace("'", "''")}'" for v in data.values())

        return f"INSERT INTO {table} ({columns_clause}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        query_parts = [f'DELETE FROM {table}']

        if where and isinstance(where, dict):
            conditions = []
            for key, value in where.items():
                # Escape single quotes to prevent SQL injection
                escaped_value = str(value).replace("'", "''")
                conditions.append(f"{key}='{escaped_value}'")

            if conditions:
                query_parts.append(f"WHERE {' AND '.join(conditions)}")

        return ' '.join(query_parts)

    @staticmethod
    def update(table, data, where=None):
        if not isinstance(data, dict) or not data:
            raise ValueError("data must be a non-empty dictionary")

        table_clause = f'UPDATE {table}'

        # Build SET clause
        set_parts = []
        for key, value in data.items():
            escaped_value = str(value).replace("'", "''")
            set_parts.append(f"{key}='{escaped_value}'")
        set_clause = ', '.join(set_parts)

        query_parts = [f'{table_clause} SET {set_clause}']

        # Build WHERE clause
        if where and isinstance(where, dict):
            conditions = []
            for key, value in where.items():
                escaped_value = str(value).replace("'", "''")
                conditions.append(f"{key}='{escaped_value}'")

            if conditions:
                query_parts.append(f"WHERE {' AND '.join(conditions)}")

        return ' '.join(query_parts)
